const raw = $input.first().json['Suspicious message or link'] || '';
const text = String(raw);

// 1. URLs (with or without http)
const urlRegex = /(?:https?:\/\/|www\.)[^\s<>"')]+/gi;
let urls = (text.match(urlRegex) || []).map(u => u.replace(/[.,;!?]+$/, ''));

// 2. Bare domains such as amaz0n-careers.in
if (urls.length === 0) {
  const bare = /\b(?:[a-z0-9-]+\.)+(?:com|in|co|net|org|xyz|top|info|online|site|link|club|biz|shop|app|live|work|click)\b(?:\/[^\s]*)?/gi;
  urls = (text.match(bare) || []).filter(d => !/@/.test(text.substr(Math.max(0, text.indexOf(d) - 1), 1)));
}

let domain = '';
if (urls.length) {
  const m = urls[0].replace(/^https?:\/\//i, '').match(/^([^\/?#:\s]+)/);
  if (m) domain = m[1].replace(/^www\./i, '').toLowerCase();
}

const shorteners = ['bit.ly','tinyurl.com','t.co','goo.gl','cutt.ly','is.gd','rb.gy','shorturl.at','wa.me','ow.ly'];
const isShortener = shorteners.some(s => domain === s);

const lower = text.toLowerCase();
const urgencyWords = ['urgent','immediately','within 24 hours','last chance','act now','expires today','limited slots','hurry','final notice','today only'];
const feeWords = ['registration fee','processing fee','security deposit','refundable','joining fee','training fee','kit fee','pay to confirm'];
const sensitiveWords = ['otp','pin','password','cvv','aadhaar','aadhar','pan card','bank details','card number','upi pin'];
const redirectWords = ['whatsapp','telegram','signal','contact on','dm me','text me'];

const hits = list => list.filter(w => lower.includes(w));
const money = text.match(/(?:₹|rs\.?|inr|\$|usd)\s?\d[\d,]*/gi) || [];
const phones = text.match(/(?:\+?91[\s-]?)?[6-9]\d{9}/g) || [];
const emails = text.match(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}/g) || [];
const freeProviders = ['gmail.com','yahoo.com','outlook.com','hotmail.com','rediffmail.com','proton.me'];
const freeEmails = emails.filter(e => freeProviders.includes(e.split('@')[1].toLowerCase()));

return [{
  json: {
    message: text,
    urls,
    domain,
    hasDomain: domain !== '',
    isShortener,
    urgencyHits: hits(urgencyWords),
    feeHits: hits(feeWords),
    sensitiveHits: hits(sensitiveWords),
    redirectHits: hits(redirectWords),
    moneyMentions: money,
    phones,
    emails,
    freeEmails
  }
}];

const f = $('Extract Features').first().json;
const allEvents = $input.all().flatMap(i => (i.json && Array.isArray(i.json.events)) ? i.json.events : []);

// Domain age from RDAP (if available)
let registered = null, ageDays = null;
if (allEvents.length) {
  const ev = allEvents.find(e => e.eventAction === 'registration');
  if (ev && ev.eventDate) {
    registered = ev.eventDate;
    ageDays = Math.floor((Date.now() - new Date(ev.eventDate).getTime()) / 86400000);
  }
}

// Lookalike brand check
const brands = ['amazon','google','microsoft','paypal','flipkart','paytm','phonepe','sbi','hdfc','icici','linkedin','naukri','internshala','tcs','infosys','wipro','accenture','cognizant'];
const norm = f.domain.replace(/0/g,'o').replace(/1/g,'l').replace(/3/g,'e').replace(/5/g,'s');
const lookalike = brands.filter(b => {
  if (!norm.includes(b)) return false;
  const official = [b + '.com', b + '.in', b + '.co.in', b + '.org'];
  return !official.includes(f.domain) && !official.some(o => f.domain.endsWith('.' + o));
});

const lines = [];
lines.push('MESSAGE:\n' + f.message);
lines.push('\nTECHNICAL EVIDENCE:');
lines.push('- URLs found: ' + (f.urls.length ? f.urls.join(', ') : 'none'));
lines.push('- Main domain: ' + (f.domain || 'none'));
lines.push('- URL shortener used: ' + f.isShortener);
lines.push('- Domain registered: ' + (registered || 'unknown (lookup failed or no domain)'));
lines.push('- Domain age in days: ' + (ageDays === null ? 'unknown' : ageDays));
lines.push('- Lookalike of known brand: ' + (lookalike.length ? lookalike.join(', ') : 'none detected'));
lines.push('\nLANGUAGE SIGNALS:');
lines.push('- Urgency phrases: ' + (f.urgencyHits.join(', ') || 'none'));
lines.push('- Fee or payment phrases: ' + (f.feeHits.join(', ') || 'none'));
lines.push('- Asks for sensitive info: ' + (f.sensitiveHits.join(', ') || 'none'));
lines.push('- Asks to move to another app: ' + (f.redirectHits.join(', ') || 'none'));
lines.push('- Money amounts: ' + (f.moneyMentions.join(', ') || 'none'));
lines.push('- Phone numbers: ' + (f.phones.join(', ') || 'none'));
lines.push('- Email addresses: ' + (f.emails.join(', ') || 'none'));
lines.push('- Free-provider emails: ' + (f.freeEmails.join(', ') || 'none'));

return [{ json: { ...f, domainAgeDays: ageDays, lookalike, evidenceText: lines.join('\n') } }];

const o = $json.output || {};
const esc = s => String(s ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');
const list = arr => (Array.isArray(arr) && arr.length)
  ? '<ul>' + arr.map(x => '<li>' + esc(x) + '</li>').join('') + '</ul>'
  : '<p>None found</p>';

const score = Number(o.risk_score ?? 0);
const color = score >= 70 ? '#c0392b' : score >= 40 ? '#e67e22' : '#27ae60';

const html =
  '<div style="font-family:sans-serif">' +
  '<h2 style="color:' + color + '">' + esc(o.verdict) + ' (' + score + '/100)</h2>' +
  '<p><b>Likely type:</b> ' + esc(o.scam_type) + '</p>' +
  '<h3>Red flags</h3>' + list(o.red_flags) +
  '<h3>Reassuring signals</h3>' + list(o.safe_signals) +
  '<h3>What to do</h3>' + list(o.what_to_do) +
  '<p style="font-size:12px;color:#777">This is an automated estimate, not a guarantee. Always verify through the official website or a trusted person.</p>' +
  '</div>';

return [{ json: { html } }];
